import time, re
from pathlib import Path
import mujoco, numpy as np
xml0=Path('model_ref.xml').read_text()

def make(name):
    x=xml0
    if name=='contactoff': x=x.replace('type="capsule" size=".005"', 'type="capsule" size=".005" contype="0" conaffinity="0"')
    elif name.startswith('opt:'):
        attrs=name[4:]
        x=x.replace('<compiler autolimits="true"/>', '<compiler autolimits="true"/>\n  <option '+attrs+'/>')
    return x

def state(m, seed):
    d=mujoco.MjData(m)
    d.qpos += np.random.default_rng(seed).normal(0,.01,size=d.qpos.shape)
    mujoco.mj_forward(m,d)
    for _ in range(int(2/m.opt.timestep)): mujoco.mj_step(m,d)
    s=np.zeros(mujoco.mj_stateSize(m,mujoco.mjtState.mjSTATE_FULLPHYSICS))
    mujoco.mj_getState(m,d,s,mujoco.mjtState.mjSTATE_FULLPHYSICS)
    return s

def timed(m, n=4):
    out=[]
    for seed in range(n):
      d=mujoco.MjData(m); d.qpos += np.random.default_rng(seed+101).normal(0,.01,size=d.qpos.shape); mujoco.mj_forward(m,d)
      t=time.perf_counter()
      for _ in range(int(2/m.opt.timestep)): mujoco.mj_step(m,d)
      s=np.zeros(mujoco.mj_stateSize(m,mujoco.mjtState.mjSTATE_FULLPHYSICS)); mujoco.mj_getState(m,d,s,mujoco.mjtState.mjSTATE_FULLPHYSICS)
      out.append(time.perf_counter()-t)
    return np.mean(out), np.std(out)

ref=mujoco.MjModel.from_xml_string(xml0)
print('ref opts',ref.opt.timestep,ref.opt.integrator,ref.opt.solver,ref.opt.jacobian,ref.opt.iterations,ref.opt.ls_iterations)
rstates={seed:state(ref,seed) for seed in range(3)}
variants=['contactoff','opt:jacobian="sparse"','opt:solver="CG"','opt:solver="PGS"','opt:solver="Newton" iterations="1"','opt:solver="Newton" iterations="1" ls_iterations="1"','opt:solver="CG" jacobian="sparse"','opt:solver="PGS" jacobian="sparse"','opt:jacobian="sparse" iterations="1"','opt:integrator="implicitfast"','opt:integrator="implicit"','opt:integrator="RK4"']
for name in variants:
 try:
  m=mujoco.MjModel.from_xml_string(make(name))
  diffs=[]
  for seed in range(3):
   s=state(m,seed); diffs.append(np.max(np.abs(s-rstates[seed])))
  tt=timed(m)
  print(name,'opts',m.opt.timestep,m.opt.integrator,m.opt.solver,m.opt.jacobian,m.opt.iterations,m.opt.ls_iterations,'diff',diffs,'time',tt)
 except Exception as e: print(name,'ERROR',type(e).__name__,e)
PY
